        } catch (error) {
          importError = String(error) + " " + (error.stack || "")
        }
        return { dragPins, importError, hasController: window.Stimulus.router.modulesByIdentifier.has("drag-and-drop") }
      })()
    JS
    puts info.inspect
  end
